const std = @import("std");

const zdiff = @import("root.zig");

// The bench code and the generator.sh is generated by claude

const Sample = struct {
    label: []const u8,
    n: usize,
    m: usize,
    d: usize,
    script_len: usize,
    core_ns: i128,
    full_ns: i128,
};

fn measure(
    alloc: std.mem.Allocator,
    io: std.Io,
    label: []const u8,
    a: []const u8,
    b: []const u8,
    reps: usize,
) !Sample {
    var s: Sample = .{
        .label = label,
        .n = a.len,
        .m = b.len,
        .d = 0,
        .script_len = 0,
        .core_ns = std.math.maxInt(i64),
        .full_ns = std.math.maxInt(i64),
    };

    { // warmup, non misurato
        var w = try zdiff.diff(alloc, a, b, 6726);
        w.deinit(alloc);
    }

    for (0..reps) |_| {
        const t0 = std.Io.Clock.now(.awake, io);
        const d = (try zdiff.shortestEdit(alloc, a, b, 6726)).?;
        const t1 = std.Io.Clock.now(.awake, io);
        var script = try zdiff.diff(alloc, a, b, 6726);
        const t2 = std.Io.Clock.now(.awake, io);
        defer script.deinit(alloc);

        s.d = d;
        s.script_len = script.items.len;
        s.core_ns = @min(s.core_ns, t0.durationTo(t1).toNanoseconds());
        s.full_ns = @min(s.full_ns, t1.durationTo(t2).toNanoseconds());
    }
    return s;
}
fn benchSynthetic(alloc: std.mem.Allocator, io: std.Io, reps: usize) !void {
    var prng = std.Random.DefaultPrng.init(0xC0FFEE);
    const r = prng.random();

    std.debug.print("== sintetico (sweep su D) ==\n", .{});
    for ([_]usize{ 1000, 4000, 16000 }) |n| {
        for ([_]usize{ 0, 1, 10, 100, 1000 }) |muts| {
            if (muts > n / 4) continue;

            const a = try alloc.alloc(u8, n);
            defer alloc.free(a);
            for (a) |*c| c.* = r.int(u8);
            const b = try alloc.dupe(u8, a);
            defer alloc.free(b);
            for (0..muts) |_| b[r.uintLessThan(usize, n)] = r.int(u8);

            const s = try measure(alloc, io, "-", a, b, reps);
            const cells = @as(f64, @floatFromInt(s.d)) * @as(f64, @floatFromInt(s.d)) / 2.0;
            const work = cells + @as(f64, @floatFromInt(s.n));
            std.debug.print(
                "n={d:>6} D={d:>5} len={d:>6} | core {d:>10} ns | full {d:>10} ns | {d:>6.2} ns/cella\n",
                .{ n, s.d, s.script_len, s.core_ns, s.full_ns, if (cells > 0) @as(f64, @floatFromInt(s.core_ns)) / work else 0 },
            );
        }
        std.debug.print("\n", .{});
    }
}
fn lessByFull(_: void, a: Sample, b: Sample) bool {
    return a.full_ns < b.full_ns;
}

fn benchCorpus(alloc: std.mem.Allocator, io: std.Io, reps: usize, max_bytes: usize) !void {
    const cwd = std.Io.Dir.cwd();
    const manifest = std.Io.Dir.readFileAlloc(cwd, io, "corpus/index.txt", alloc, .unlimited) catch |e| {
        std.debug.print("corpus non disponibile ({s}), salto\n", .{@errorName(e)});
        return;
    };
    defer alloc.free(manifest); // le label sono slice dentro qui

    var samples: std.ArrayList(Sample) = .empty;
    defer samples.deinit(alloc);

    var skipped: usize = 0;
    var lines = std.mem.tokenizeScalar(u8, manifest, '\n');
    while (lines.next()) |line| {
        var cols = std.mem.tokenizeScalar(u8, line, '\t');
        const pa = cols.next() orelse continue;
        const pb = cols.next() orelse continue;

        const a = try std.Io.Dir.readFileAlloc(cwd, io, pa, alloc, .unlimited);
        defer alloc.free(a);
        const b = try std.Io.Dir.readFileAlloc(cwd, io, pb, alloc, .unlimited);
        defer alloc.free(b);

        if (a.len + b.len > max_bytes) {
            skipped += 1;
            continue;
        }
        try samples.append(alloc, try measure(alloc, io, pa, a, b, reps));
    }

    if (samples.items.len == 0) {
        std.debug.print("corpus vuoto\n", .{});
        return;
    }

    var tot_core: i128 = 0;
    var tot_full: i128 = 0;
    var tot_bytes: usize = 0;
    var tot_d: usize = 0;
    var max_d: usize = 0;
    for (samples.items) |s| {
        tot_core += s.core_ns;
        tot_full += s.full_ns;
        tot_bytes += s.n + s.m;
        tot_d += s.d;
        max_d = @max(max_d, s.d);
    }

    const buckets = [_]usize{ 1, 10, 100, 1000, std.math.maxInt(usize) };
    var cnt = [_]usize{0} ** buckets.len;
    var sum = [_]i128{0} ** buckets.len;
    for (samples.items) |s| {
        for (buckets, 0..) |hi, bi| if (s.d < hi) {
            cnt[bi] += 1;
            sum[bi] += s.full_ns;
            break;
        };
    }

    std.mem.sort(Sample, samples.items, {}, lessByFull);
    const L = samples.items.len;
    const p50 = samples.items[L / 2];
    const p90 = samples.items[L * 9 / 10];
    const worst = samples.items[L - 1];

    std.debug.print("== corpus ({d} coppie, {d} saltate) ==\n", .{ L, skipped });
    std.debug.print("  bytes {d} | D medio {d} | D max {d}\n", .{ tot_bytes, tot_d / L, max_d });
    std.debug.print("  core tot {d} ns | full tot {d} ns | {d:.1} MB/s\n", .{
        tot_core,                                                                             tot_full,
        @as(f64, @floatFromInt(tot_bytes)) / (@as(f64, @floatFromInt(tot_full)) / 1e9) / 1e6,
    });
    std.debug.print("  full per coppia: p50 {d} ns | p90 {d} ns | max {d} ns ({s}, D={d}, len={d})\n", .{
        p50.full_ns, p90.full_ns, worst.full_ns, worst.label, worst.d, worst.script_len,
    });
    for (buckets, 0..) |hi, bi| {
        if (cnt[bi] == 0) continue;
        std.debug.print("    D<{d:<12} {d:>5} coppie | full medio {d:>10} ns\n", .{ hi, cnt[bi], @divTrunc(sum[bi], cnt[bi]) });
    }
    std.debug.print("\n", .{});
}

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const alloc = init.gpa;
    std.debug.print("mode: {s}\n\n", .{@tagName(@import("builtin").mode)});
    try benchSynthetic(alloc, io, 7);
    try benchCorpus(alloc, io, 5, 32 * 1024);
}
